export function latestRequestOn(repo, number, isKnownAgent): ThreadRequest {
  const { body, shaped } = readThread(repo, number);
  // A name with no definition cannot be dispatched, so each answer routes by the
  // nearest name that can be.
  const known = (name: string): string => (isKnownAgent(name) ? name : "");
  return {
    // The standing request keeps the strict read: it is what a dispatch acts on, and a
    // command a person typed is read the way the dispatch reads it.
    newestRequestedAgent: latestRequestedAgent(body, shaped.comments, {
      ...readers,
