{"path": "src/adapters/github/thread.test.ts", "content": "import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { FAKE_GH_IMPL } from "../../entrypoints/machinery/testing/fake-gh-env.ts";
import { latestRequestOn } from "./thread.ts";

/**
 * The wiring of the two answers the validation routing asks of a thread: which agent
 * the newest request names, and which ask a push could answer.
 *
 * The fold is tested in `domain/work/thread.test.ts`; what this pins is the readers it
 * is handed here. They are not the same reader any more, and the difference is the
 * whole defensibility of the routing: the ask is read the way the HANDOFF was read
 * (tolerating the markdown a model's output arrives in), while the standing request
 * keeps the strict parse a dispatch and the guard act on.
 *
 * A regression that put both on the strict parse restores #219: the directive the
 * runner posted back as `- /engineer` stops being an ask, and the green verdict
 * re-dispatches the agent the push already answered.
 */
const REPO = "o/r";
const NUMBER = 7;
const KNOWN = new Set(["engineer", "reviewer"]);

/** A comment as the issues API returns it. */
function comment(id: number, createdAt: string, body: string, type = "Bot"): unknown {
  return { id, created_at: createdAt, body, user: { type } };
}

function readThread(body: string, comments: unknown[]): void {
  process.env.ATOMATON_FAKE_GH = FAKE_GH_IMPL;
  process.env.GH_TOKEN = "fake-gh-must-be-used";
  process.env.GITHUB_TOKEN = "fake-gh-must-be-used";
  process.env.FAKE_GH_RESPONSES = JSON.stringify([
    // The body read is the one carrying `--jq`; the comments read is the one whose path
    // goes on to `/comments`.
    { match: [`repos/${REPO}/issues/${NUMBER}`, "--jq"], stdout: body },
    { match: [`repos/${REPO}/issues/${NUMBER}/comments`], stdout: JSON.stringify(comments) },
  ]);
}

const savedFake = process.env.ATOMATON_FAKE_GH;
const savedToken = process.env.GH_TOKEN;
const savedGithubToken = process.env.GITHUB_TOKEN;
const savedResponses = process.env.FAKE_GH_RESPONSES;

afterAll(() => {
  const restore = (key: string, value: string | undefined): void => {
    if (value === undefined) delete process.env[key];
    else process.env[key] = value;
  };
  restore("ATOMATON_FAKE_GH", savedFake);
  restore("GH_TOKEN", savedToken);
  restore("GITHUB_TOKEN", savedGithubToken);
  restore("FAKE_GH_RESPONSES", savedResponses);
});

describe("latestRequestOn", () => {
  beforeAll(() => {
    // Nothing here may reach the real CLI: the fake is named, and the tokens are ones
    // the real one cannot use. See `fake-gh-env.ts`.
    process.env.GH_TOKEN = "fake-gh-must-be-used";
  });

  // #219's shape, on the mangled variant: the reviewer's result comment ends with
  // `- /engineer`, the machinery takes it up, and the engineer publishes its fix. The
  // newest request in the thread is the marker naming the engineer, but the ASK is the
  // reviewer's directive -- `- /engineer` included, because that is the line the
  // handoff was read from.
  test("a markdown-mangled directive is the ask, and the marker is the standing request", () => {
    readThread("/reviewer\n\nPart of #219", [
      comment(1, "2026-10-19T17:41:32Z", `/engineer\n\n${"Problems found."}\n\nNeed a fix.\n\n- /engineer`, "Bot"),
      comment(2, "2026-10-19T17:41:46Z", "<!-- atomaton:dispatch = engineer -->\nAtomaton: `engineer` starting."),
      comment(3, "2026-10-19T18:05:00Z", "<!-- atomaton:agent=engineer -->\nFixed it."),
    ]);

    const request = latestRequestOn(REPO, NUMBER, (name) => KNOWN.has(name));
    expect(request.newestRequestedAgent).toBe("engineer");
    expect(request.latestAsk).toEqual({
      agent: "engineer",
      author: { kind: "agent", agent: "reviewer" },
      at: "2026-10-19T17:41:32Z",
    });
  });

  // The strict half, and the reason the tolerance is scoped: a person's markdown bullet
  // was never a command the machinery acted on, so it is not the standing request a
  // dispatch is routed by -- while the bare command in the same thread is.
  test("a person's bulleted command is not the standing request", () => {
    readThread("/reviewer", [comment(1, "2026-10-19T18:00:00Z", "- /engineer", "User")]);

    expect(latestRequestOn(REPO, NUMBER, (name) => KNOWN.has(name)).newestRequestedAgent).toBe("reviewer");
  });

  // The body's own `/<agent>` line is the standing request and never the ask: a push is
  // part of the work it asked for, so consuming it would hand the pull request back to
  // its opener on every push.
  test("the body's own line is the standing request, never the ask", () => {
    readThread("/reviewer\n\nPart of #219", []);

    const request = latestRequestOn(REPO, NUMBER, (name) => KNOWN.has(name));
    expect(request.newestRequestedAgent).toBe("reviewer");
    expect(request.latestAsk).toBeUndefined();
  });
});
